Binary-search a partition in the shorter array, choosing the other partition so the left half contains half the elements, rounded up. When both left boundaries are at most the opposite right boundaries, the median is the largest left value for an odd total, or the average of the two middle values for an even total. This uses O(log(min(m,n)+1)) time and O(1) extra space, and handles an empty array.

```javascript
function solve(nums1, nums2) {
  let a = nums1, b = nums2;
  if (a.length > b.length) [a, b] = [b, a];

  const m = a.length, n = b.length;
  const half = Math.floor((m + n + 1) / 2);
  let low = 0, high = m;

  while (low <= high) {
    const i = Math.floor((low + high) / 2);
    const j = half - i;

    const leftA = i === 0 ? -Infinity : a[i - 1];
    const rightA = i === m ? Infinity : a[i];
    const leftB = j === 0 ? -Infinity : b[j - 1];
    const rightB = j === n ? Infinity : b[j];

    if (leftA <= rightB && leftB <= rightA) {
      const leftMax = Math.max(leftA, leftB);
      if ((m + n) % 2 === 1) return leftMax;
      return (leftMax + Math.min(rightA, rightB)) / 2;
    }

    if (leftA > rightB) high = i - 1;
    else low = i + 1;
  }
}
```

