Use dynamic programming to match the entire string, with ? matching one character and * matching any sequence, including empty. Time: O(s.length × p.length); extra space: O(p.length). Call solve(s, p) directly.

```javascript
function solve(s, p) {
  const dp = new Array(p.length + 1).fill(false);
  dp[0] = true;

  for (let j = 1; j <= p.length; j++) {
    dp[j] = dp[j - 1] && p[j - 1] === '*';
  }

  for (let i = 1; i <= s.length; i++) {
    let diagonal = dp[0];
    dp[0] = false;

    for (let j = 1; j <= p.length; j++) {
      const above = dp[j];
      if (p[j - 1] === '*') {
        dp[j] = dp[j - 1] || above;
      } else {
        dp[j] = diagonal &&
          (p[j - 1] === '?' || p[j - 1] === s[i - 1]);
      }
      diagonal = above;
    }
  }

  return dp[p.length];
}
```

